    JSONObject json(String value)throws Exception{return new JSONObject(value);}
    @Test public void aioStreamsParsingAndChoice()throws Exception{
        JSONObject item=json("{imdb:'tt123',movie:false,season:2,episode:3}");JSONObject settings=json("{preferredResolution:'720p',language:'English',maxEpisodeBytes:2000,torBoxKey:'fixture-private'}");
        String hash="1234567890123456789012345678901234567890";
        JSONObject response=json("{streams:[{name:'1080p',url:'https://cdn.invalid/a',behaviorHints:{videoSize:1000},description:'[NOIR_AUDIO:English]'}, {infoHash:'"+hash+"',name:'Show 720p',url:'https://cdn.invalid/fixture-private',description:'[NOIR_AUDIO:English]',behaviorHints:{filename:'Show.S02E03.720p.mkv',videoSize:1500,proxyHeaders:{request:{'User-Agent':'fixture','Range':'forbidden'}}}}, {name:'Too large',url:'https://cdn.invalid/large',behaviorHints:{videoSize:3000}}, {externalUrl:'https://external.invalid/watch'}]}");
        List<JSONObject> choices=PhoneDownloadProvider.parse(response,item,settings);assertEquals(4,choices.size());List<JSONObject> ranked=PhoneDownloadProvider.ranked(choices,settings,"");assertEquals(2,ranked.size());assertEquals("720p",ranked.get(0).optString("resolution"));assertFalse(ranked.get(0).optJSONObject("headers").has("Range"));assertEquals("fixture",ranked.get(0).optJSONObject("headers").optString("User-Agent"));assertFalse(ranked.get(0).optString("name").contains("fixture-private"));
        assertEquals("https://aio.invalid/private/stream/series/tt123%3A2%3A3.json",PhoneDownloadProvider.streamUri("stremio://aio.invalid/private/manifest.json","tt123",false,2,3));
        assertEquals("https://aio.invalid/private/stream/movie/tt123.json?config=fixture",PhoneDownloadProvider.streamUri("https://aio.invalid/private/manifest.json?config=fixture","tt123",true,0,0));
        assertFalse(PhoneDownloadProvider.validUrl("file:///private"));assertFalse(PhoneDownloadProvider.validUrl("https://user:password@cdn.invalid/a"));assertArrayEquals(new int[]{2,3},PhoneDownloadProvider.episode("show.S02E03.mkv",1));
    }
    @Test public void seasonScopesAndStableIds()throws Exception{
        List<JSONObject> episodes=new ArrayList<>();for(int s=1;s<=2;s++)for(int e=1;e<=5;e++)episodes.add(json("{id:'"+s+"-"+e+"',season:"+s+",episode:"+e+",airsAt:'2020-01-01T00:00:00Z'}"));DataStore.put(episodes.get(0),"progress",json("{completed:true}"));DataStore.put(episodes.get(4),"airsAt","2099-01-01T00:00:00Z");Set<String> saved=Set.of("1-2");long now=System.currentTimeMillis();
        assertEquals(3,PhoneSeasonPlan.select(episodes,1,"Missing on phone","1",saved,now).size());assertEquals(2,PhoneSeasonPlan.select(episodes,1,"Unwatched","1",saved,now).size());assertEquals(2,PhoneSeasonPlan.select(episodes,1,"From episode N","3",saved,now).size());assertEquals("1-3",PhoneSeasonPlan.select(episodes,1,"Next N","1",saved,now).get(0).optString("id"));assertEquals(2,PhoneSeasonPlan.select(episodes,1,"Specific episodes","1,4",saved,now).size());assertEquals(8,PhoneSeasonPlan.select(episodes,1,"Several seasons","1-2",saved,now).size());
        assertEquals("episode-"+DiscoveryClient.hash("show:tt123:2:3"),PhoneSeasonPlan.episodeId("show:tt123",2,3));
        JSONObject title=json("{id:'tt123',name:'Fixture',noirType:'series',videos:[{season:1,episode:1,name:'First'},{season:1,episode:2,name:'Second'}]}");List<JSONObject> discovered=PhoneSeasonPlan.discoverItems(title);assertEquals("discover-series-tt123",discovered.get(0).optString("id"));assertEquals(PhoneSeasonPlan.episodeId("show:tt123",1,2),discovered.get(1).optString("id"));
    }
    Context isolated(){Context real=InstrumentationRegistry.getInstrumentation().getTargetContext();File root=new File(real.getFilesDir(),"phone-tests-"+UUID.randomUUID());root.mkdirs();return new ContextWrapper(real){@Override public Context getApplicationContext(){return this;}@Override public File getFilesDir(){return root;}@Override public File getExternalFilesDir(String type){File external=new File(root,"external");external.mkdirs();return external;}};}
    @Test public void encryptedSettingsAndSourcesSurviveReopen()throws Exception{
        Context context=isolated();PhoneDownloadSettings settings=new PhoneDownloadSettings(context);JSONObject config=json("{manifest:'https://aio.invalid/private-fixture/manifest.json',torBoxKey:'fixture-secret',realDebridKey:'fixture-rd'}");settings.save(config);String disk=new String(Files.readAllBytes(new File(context.getFilesDir(),"phone-download-settings.enc").toPath()),StandardCharsets.UTF_8);assertFalse(disk.contains("fixture-secret"));assertFalse(disk.contains("private-fixture"));assertEquals("fixture-secret",new PhoneDownloadSettings(context).load().optString("torBoxKey"));assertNotEquals(settings.seal("same"),settings.seal("same"));
    }
