    @Test public void nativeTorBoxPackNeedsNoPc()throws Exception{
        String hash="1234567890123456789012345678901234567890";List<String> calls=new ArrayList<>();
        JSONObject config=json("{torBoxKey:'fixture-key'}");PhoneDownloadProvider provider=new PhoneDownloadProvider(config,(url,key,form,multipart)->{
            assertEquals("fixture-key",key);calls.add(url);
            if(url.contains("checkcached"))return json("{success:true,data:[{hash:'"+hash+"',files:[{id:5,name:'Show.S02E03.mkv',size:200}]}]}");
            if(url.endsWith("mylist?bypass_cache=true"))return json("{success:true,data:[]}");
            if(url.endsWith("createtorrent")){assertTrue(multipart);assertEquals("magnet:?xt=urn:btih:"+hash,form.get("magnet"));return json("{success:true,data:{torrent_id:42}}");}
            if(url.contains("mylist?id=42"))return json("{success:true,data:[{hash:'"+hash+"',download_present:true,files:[{id:5,name:'Show.S02E03.mkv',size:200}]}]}");
            if(url.contains("requestdl")){assertTrue(url.contains("file_id=5"));return json("{success:true,data:'https://cdn.invalid/torbox'}");}throw new AssertionError("Unexpected TorBox operation");
        });
        JSONObject pack=json("{hash:'"+hash+"',service:'torbox',name:'Show 1080p',pack:true}");JSONObject item=json("{season:2,episode:3}");List<JSONObject> files=provider.files(pack,item);assertEquals(3,files.get(0).optInt("episode"));assertEquals("https://cdn.invalid/torbox",provider.resolve(files.get(0),item,()->false).optString("url"));assertTrue(calls.stream().anyMatch(s->s.contains("createtorrent")));
    }
    @Test public void nativeRealDebridSelectionMapsTheCorrectLink()throws Exception{
        String hash="1234567890123456789012345678901234567890";boolean[] selected={false};PhoneDownloadProvider provider=new PhoneDownloadProvider(json("{realDebridKey:'fixture-rd'}"),(url,key,form,multipart)->{
            assertEquals("fixture-rd",key);assertFalse(multipart);
            if(url.contains("torrents?"))return new JSONArray();
            if(url.endsWith("addMagnet")){assertEquals("magnet:?xt=urn:btih:"+hash,form.get("magnet"));return json("{id:'ABC'}");}
            if(url.endsWith("info/ABC"))return json("{hash:'"+hash+"',status:'"+(selected[0]?"downloaded":"waiting_files_selection")+"',files:[{id:1,path:'/Show.S02E02.mkv',bytes:100,selected:1},{id:7,path:'/Show.S02E03.mkv',bytes:200,selected:1}],links:['https://rd.invalid/first','https://rd.invalid/second']}");
            if(url.endsWith("selectFiles/ABC")){assertEquals("1,7",form.get("files"));selected[0]=true;return new JSONObject();}
            if(url.endsWith("unrestrict/link")){assertEquals("https://rd.invalid/second",form.get("link"));return json("{download:'https://cdn.invalid/rd'}");}throw new AssertionError("Unexpected RD operation");
        });
        JSONObject item=json("{season:2,episode:3}"),pack=json("{hash:'"+hash+"',service:'rd',pack:true}");List<JSONObject> files=provider.files(pack,item);assertEquals("https://cdn.invalid/rd",provider.resolve(files.get(1),item,()->false).optString("url"));assertTrue(selected[0]);
    }
    @Test public void expiredDirectLinkRepeatsEpisodeSearchWithoutPc()throws Exception{
        Context context=isolated();DataStore previous=NoirApp.data;DataStore data=new DataStore(context);NoirApp.data=data;ExecutorService server=Executors.newSingleThreadExecutor();
        try(ServerSocket socket=new ServerSocket(0,2,InetAddress.getByName("127.0.0.1"))){socket.setSoTimeout(15000);String base="http://127.0.0.1:"+socket.getLocalPort();boolean[] searched={false};
            Future<?> served=server.submit(()->{try{for(int n=0;n<2;n++)try(Socket client=socket.accept()){BufferedReader input=new BufferedReader(new InputStreamReader(client.getInputStream(),StandardCharsets.US_ASCII));String request=input.readLine();String line;while((line=input.readLine())!=null&&!line.isEmpty()){}OutputStream output=client.getOutputStream();if(n==0){assertTrue(request.contains("/expired"));output.write("HTTP/1.1 403 Forbidden\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".getBytes(StandardCharsets.US_ASCII));}else{assertTrue(request.contains("/fresh"));output.write("HTTP/1.1 200 OK\r\nContent-Length: 4\r\nETag: \"new\"\r\nConnection: close\r\n\r\nDATA".getBytes(StandardCharsets.US_ASCII));}output.flush();}}catch(Exception e){throw new RuntimeException(e);}});
            PhoneDownloadSettings settings=new PhoneDownloadSettings(context);settings.save(json("{manifest:'https://aio.invalid/private/manifest.json'}"));DownloadStore store=new DownloadStore(context,c->new PhoneDownloadProvider(c,(url,key,form,multipart)->{assertEquals("https://aio.invalid/private/stream/series/tt987654%3A2%3A3.json",url);assertEquals("",key);searched[0]=true;return json("{streams:[{url:'"+base+"/fresh',behaviorHints:{filename:'Fixture.S02E03.mkv',videoSize:4}}]}");}));
            JSONObject item=json("{id:'discover-series-tt987654',title:'Fixture',group:'show:tt987654',imdb:'tt987654',season:2,episode:3}"),choice=json("{service:'direct',name:'Fixture.S02E03.mkv',url:'"+base+"/expired',size:4}");store.enqueuePhone(item,choice);store.transfer(item.optString("id"),j->{});served.get(15,TimeUnit.SECONDS);assertTrue(searched[0]);assertEquals("complete",store.job(item.optString("id")).optString("status"));assertEquals("DATA",new String(Files.readAllBytes(store.file(item.optString("id"),false).toPath()),StandardCharsets.US_ASCII));assertFalse(data.paired());
        }finally{NoirApp.data=previous;data.network.shutdownNow();data.images.shutdownNow();server.shutdownNow();}
    }
    @Test public void foregroundDownloadFinishesWithScreenOffAndPlaysOffline()throws Exception{
        Context context=isolated();DataStore previousData=NoirApp.data;DownloadStore previousDownloads=NoirApp.downloads;DataStore data=new DataStore(context);DownloadStore store=new DownloadStore(context);NoirApp.data=data;NoirApp.downloads=store;
        android.app.Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();ExecutorService server=Executors.newSingleThreadExecutor();CountDownLatch background=new CountDownLatch(1);DownloadsActivity[] screen={null};PlayerActivity[] player={null};
        try(ServerSocket socket=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"))){socket.setSoTimeout(20000);byte[] video;try(InputStream input=instrumentation.getContext().getAssets().open("phone-offline-fixture.mkv")){video=DataStore.read(input,1024*1024);}
            Future<?> served=server.submit(()->{try(Socket client=socket.accept()){client.setSoTimeout(20000);BufferedReader input=new BufferedReader(new InputStreamReader(client.getInputStream(),StandardCharsets.US_ASCII));String line;while((line=input.readLine())!=null&&!line.isEmpty()){}if(!background.await(15,TimeUnit.SECONDS))throw new AssertionError("App never entered background");OutputStream output=client.getOutputStream();output.write(("HTTP/1.1 200 OK\r\nContent-Length: "+video.length+"\r\nETag: \"offline-video\"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));output.write(video);output.flush();}catch(Exception e){throw new RuntimeException(e);}});
            JSONObject item=json("{id:'discover-movie-tt987650',title:'Offline playback fixture',group:'movie:tt987650',imdb:'tt987650',movie:true}");JSONObject choice=json("{service:'direct',name:'Offline movie',url:'http://127.0.0.1:"+socket.getLocalPort()+"/movie',size:"+video.length+"}");store.enqueuePhone(item,choice);
            screen[0]=(DownloadsActivity)instrumentation.startActivitySync(new Intent(instrumentation.getTargetContext(),DownloadsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));instrumentation.runOnMainSync(()->screen[0].startForegroundService(new Intent(screen[0],DownloadService.class)));
            instrumentation.getUiAutomation().executeShellCommand("input keyevent KEYCODE_HOME").close();instrumentation.getUiAutomation().executeShellCommand("input keyevent KEYCODE_SLEEP").close();Thread.sleep(700);assertFalse(instrumentation.getTargetContext().getSystemService(android.os.PowerManager.class).isInteractive());background.countDown();
            String id=item.optString("id");for(int n=0;n<100&&!store.job(id).optString("status").equals("complete");n++)Thread.sleep(100);served.get(15,TimeUnit.SECONDS);assertEquals(store.job(id).toString(),"complete",store.job(id).optString("status"));assertFalse(data.paired());assertArrayEquals(video,Files.readAllBytes(store.file(id,false).toPath()));
            instrumentation.getUiAutomation().executeShellCommand("input keyevent KEYCODE_WAKEUP").close();instrumentation.getUiAutomation().executeShellCommand("wm dismiss-keyguard").close();Thread.sleep(300);
            player[0]=(PlayerActivity)instrumentation.startActivitySync(new Intent(instrumentation.getTargetContext(),PlayerActivity.class).putExtra("id",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int n=0;n<150&&(player[0].player==null||!player[0].player.isPlaying());n++)Thread.sleep(100);assertNotNull(player[0].player);assertTrue("Downloaded movie must play with no paired PC: "+player[0].message.getText()+" state="+player[0].player.getPlayerState(),player[0].player.isPlaying());assertNull(player[0].proxy);
        }finally{background.countDown();instrumentation.getUiAutomation().executeShellCommand("input keyevent KEYCODE_WAKEUP").close();instrumentation.runOnMainSync(()->{if(player[0]!=null)player[0].finish();if(screen[0]!=null)screen[0].finish();instrumentation.getTargetContext().stopService(new Intent(instrumentation.getTargetContext(),DownloadService.class));});instrumentation.waitForIdleSync();if(player[0]!=null){for(int n=0;n<100;n++){boolean[] destroyed={false};instrumentation.runOnMainSync(()->destroyed[0]=player[0].destroyed);if(destroyed[0])break;Thread.sleep(50);}}NoirApp.data=previousData;NoirApp.downloads=previousDownloads;data.network.shutdownNow();data.images.shutdownNow();server.shutdownNow();}
    }
    void transferFixture(boolean restart)throws Exception{
        Context context=isolated();DataStore previousData=NoirApp.data;DownloadStore previousDownloads=NoirApp.downloads;DataStore data=new DataStore(context);DownloadStore store=new DownloadStore(context);NoirApp.data=data;NoirApp.downloads=store;assertFalse(data.paired());
        byte[] expected=new byte[65536];for(int n=0;n<expected.length;n++)expected[n]=(byte)(n%251);
        ExecutorService server=Executors.newSingleThreadExecutor();
        try(ServerSocket socket=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"))){socket.setSoTimeout(15000);Future<String> request=server.submit(()->{try(Socket client=socket.accept()){client.setSoTimeout(15000);BufferedReader input=new BufferedReader(new InputStreamReader(client.getInputStream(),StandardCharsets.US_ASCII));StringBuilder lines=new StringBuilder();String line;while((line=input.readLine())!=null&&!line.isEmpty())lines.append(line).append('\n');int start=restart?0:1024;OutputStream out=client.getOutputStream();out.write(((restart?"HTTP/1.1 200 OK\r\n":"HTTP/1.1 206 Partial Content\r\nContent-Range: bytes 1024-65535/65536\r\n")+"ETag: \""+(restart?"new":"fixture")+"\"\r\nContent-Length: "+(expected.length-start)+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(expected,start,expected.length-start);out.flush();return lines.toString();}});
            JSONObject item=json("{id:'discover-movie-tt987654',title:'Standalone fixture',movie:true,imdb:'tt987654',group:'movie:tt987654'}");JSONObject choice=json("{service:'direct',name:'Fixture',size:65536,headers:{}} ");DataStore.put(choice,"url","http://127.0.0.1:"+socket.getLocalPort()+"/video?token=fixture-private-source");store.enqueuePhone(item,choice);String id=item.optString("id");try(FileOutputStream part=new FileOutputStream(store.file(id,true))){part.write(expected,0,1024);}store.update(id,"queued",1024,65536,"\"fixture\"","");
            String queue=new String(Files.readAllBytes(new File(context.getFilesDir(),"downloads.json").toPath()),StandardCharsets.UTF_8);assertFalse(queue.contains("fixture-private-source"));store=new DownloadStore(context);NoirApp.downloads=store;store.transfer(id,j->{});assertEquals(store.job(id).toString(),"complete",store.job(id).optString("status"));String headers=request.get(15,TimeUnit.SECONDS).toLowerCase(Locale.ROOT);assertTrue(headers.contains("range: bytes=1024-"));assertTrue(headers.contains("if-range: \"fixture\""));assertArrayEquals(expected,Files.readAllBytes(store.file(id,false).toPath()));assertTrue(data.localFile(id).startsWith("file:"));assertNotNull(new DataStore(context).item(id));
            String viewing=UUID.randomUUID().toString();data.progress(id,viewing,127.5,1800,false);DataStore reopened=new DataStore(context);assertEquals(127.5,reopened.item(id).getJSONObject("progress").getDouble("position"),.001);assertEquals(1,reopened.pendingCount("progress"));assertEquals("tt987654",reopened.items().getJSONObject(0).optString("imdb"));reopened.network.shutdownNow();reopened.images.shutdownNow();
        }finally{NoirApp.data=previousData;NoirApp.downloads=previousDownloads;data.network.shutdownNow();data.images.shutdownNow();server.shutdownNow();}
    }
